import ast
src = "import os\nimport sys as system\nfrom math import sqrt\n"
tree = ast.parse(src)
for node in ast.walk(tree):
    if isinstance(node, ast.Import):
        for n in node.names: print("import", n.name)
    elif isinstance(node, ast.ImportFrom):
        print("from", node.module, "import", ", ".join(n.name for n in node.names))

