import ast
src = "def search(q, limit=10, *, exact=False):\n    pass\n"
tree = ast.parse(src)
for node in ast.walk(tree):
    if isinstance(node, ast.FunctionDef):
        d = len(node.args.defaults)
        args = node.args.args
        sig = []
        for i, a in enumerate(args):
            if i >= len(args) - d: sig.append(a.arg + "=" + ast.unparse(node.args.defaults[i - (len(args) - d)]))
            else: sig.append(a.arg)
        print(node.name + "(" + ", ".join(sig) + ")")

